import{_ as r,o as t,c as l,ao as o,j as a,a as i}from"./chunks/framework.BidoV56E.js";const b=JSON.parse('{"title":"Choose R, Julia, or the bridge","description":"","frontmatter":{},"headers":[],"relativePath":"choose-r-julia-bridge.md","filePath":"choose-r-julia-bridge.md","lastUpdated":null}'),s={name:"choose-r-julia-bridge.md"},n={class:"MathJax",jax:"SVG",overflow:"linebreak"},d={style:{"vertical-align":"-0.566ex"},xmlns:"http://www.w3.org/2000/svg",width:"1.138ex",height:"2.262ex",role:"img",focusable:"false",viewBox:"0 -750 503 1000"},h={style:{"vertical-align":"-0.566ex"},xmlns:"http://www.w3.org/2000/svg",width:"3.62ex",height:"2.262ex",role:"img",focusable:"false",viewBox:"0 -750 1600.2 1000"};function u(m,e,p,C,g,c){return t(),l("div",null,[e[5]||(e[5]=o('<h1 id="Choose-R,-Julia,-or-the-bridge" tabindex="-1">Choose R, Julia, or the bridge <a class="header-anchor" href="#Choose-R,-Julia,-or-the-bridge" aria-label="Permalink to &quot;Choose R, Julia, or the bridge {#Choose-R,-Julia,-or-the-bridge}&quot;">​</a></h1><div class="gllvm-route gllvm-route--start"><div><span class="gllvm-route__eyebrow">Pick a route</span><p>Choose the language that fits your data and workflow. The packages overlap, but they do not offer the same models.</p></div></div><p>GLLVModels.jl is the matrix-first Julia companion to R <code>gllvmTMB</code>. The R package remains the formula-first model surface and the richer applied article set. The packages share core estimands; they do not offer identical workflows, and they are not a menu of interchangeable Julia optimisers.</p><h2 id="Use-R-gllvmTMB" tabindex="-1">Use R (<code>gllvmTMB</code>) <a class="header-anchor" href="#Use-R-gllvmTMB" aria-label="Permalink to &quot;Use R (`gllvmTMB`) {#Use-R-gllvmTMB}&quot;">​</a></h2><p>Start in R when you want the formula-first teaching route or the applied article set.</p><ul><li><p>Get started: <a href="https://itchyshin.github.io/gllvmTMB/articles/gllvmTMB.html" target="_blank" rel="noreferrer">R get-started guide</a></p></li><li><p>What that route currently supports: <a href="https://itchyshin.github.io/gllvmTMB/articles/current-limits.html" target="_blank" rel="noreferrer">current limits</a></p></li></ul><p>Those limits belong to the R package. Calling Julia does not lift them.</p><h2 id="Use-Julia-GLLVModels.jl" tabindex="-1">Use Julia (<code>GLLVModels.jl</code>) <a class="header-anchor" href="#Use-Julia-GLLVModels.jl" aria-label="Permalink to &quot;Use Julia (`GLLVModels.jl`) {#Use-Julia-GLLVModels.jl}&quot;">​</a></h2>',8)),a("p",null,[e[3]||(e[3]=i("Start in Julia when you already have a response matrix and want the matrix-first companion. Responses are rows and sites are columns (",-1)),a("mjx-container",n,[(t(),l("svg",d,[...e[0]||(e[0]=[a("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[a("g",{"data-mml-node":"math","data-latex":"p \\times n"},[a("g",{"data-mml-node":"mi","data-latex":"p"},[a("path",{"data-c":"1D45D",d:"M355 442C311 442 269 419 228 373C217 419 186 442 137 442C96 442 66 409 45 344C35 311 30 292 30 286C30 277 35 272 46 272C51 272 54 273 57 275C62 284 65 291 66 298C84 374 107 412 134 412C152 412 161 398 161 371C161 356 159 339 154 321L44-118C35-151 34-155-5-155C-23-155-32-163-32-178C-32-189-26-194-15-194C0-194 52-191 67-191C86-191 146-194 165-194C180-194 187-186 187-170C187-160 178-155 159-155C141-155 114-156 114-144C114-131 155 26 159 43C179 6 209-13 249-13C314-13 371 20 421 87C467 148 490 213 490 280C490 367 438 442 355 442M352 412C391 412 411 382 411 323C411 296 405 260 394 215C371 128 342 71 307 42C286 25 267 16 248 16C219 16 199 29 188 56C179 77 174 92 174 100L225 309C230 331 248 354 276 377C304 400 329 412 352 412Z"})])])],-1)])])),e[2]||(e[2]=a("mjx-break",{size:"3"}," ",-1)),(t(),l("svg",h,[...e[1]||(e[1]=[o('<g stroke="currentColor" fill="currentColor" stroke-width="0" transform="scale(1,-1)"><g data-mml-node="math" data-latex="p \\times n"><g data-mml-node="mo" data-latex="\\times"><path data-c="D7" d="M630 32C630 39 628 44 623 49L422 250L623 451C628 456 630 461 630 468C630 481 620 491 607 491C600 491 595 489 590 484L389 283L188 484C183 489 178 491 171 491C158 491 148 481 148 468C148 461 150 456 155 451L356 250L155 49C150 44 148 39 148 32C148 19 158 9 171 9C178 9 183 11 188 16L389 217L590 16C595 11 600 9 607 9C620 9 630 19 630 32Z"></path></g><g data-mml-node="mi" data-latex="n" transform="translate(1000.2,0)"><path data-c="1D45B" d="M537 137C514 58 481 18 440 18C427 18 420 28 420 47C420 61 426 84 438 115C478 224 498 296 498 333C498 403 451 442 381 442C322 442 271 416 230 363C222 407 187 442 136 442C80 442 58 390 44 345C34 313 29 294 29 287C29 278 34 273 45 273C50 273 53 274 56 276C61 285 64 292 65 299C83 375 106 413 133 413C151 413 160 399 160 371C160 358 155 331 144 290L87 63C84 50 78 24 78 19C78-1 89-11 111-11C130-11 144-1 151 19C153 24 159 49 170 92L191 181L221 295C232 318 249 341 270 365C299 397 335 413 378 413C411 413 427 391 427 348C427 310 406 234 363 120C356 102 353 87 353 74C353 25 390-11 438-11C482-11 517 14 542 64C561 104 571 131 571 144C571 153 566 158 555 158C552 158 537 149 537 137Z"></path></g></g></g>',1)])]))]),e[4]||(e[4]=i("). Only the families and post-fit tools described in the documentation should be treated as available; overlap with R does not make the two workflows interchangeable.",-1))]),e[6]||(e[6]=o('<ul><li><p>First fit and the R ⟷ Julia conversion table: <a href="./quickstart">Quick start</a></p></li><li><p>What is currently available in both packages: <a href="./gllvmtmb-parity">Capability parity</a></p></li></ul><h2 id="Use-the-bridge-one-way-R-Julia-only" tabindex="-1">Use the bridge (one-way R → Julia only) <a class="header-anchor" href="#Use-the-bridge-one-way-R-Julia-only" aria-label="Permalink to &quot;Use the bridge (one-way R → Julia only) {#Use-the-bridge-one-way-R-Julia-only}&quot;">​</a></h2><p>The bridge is <code>gllvmTMB(..., engine = &quot;julia&quot;)</code>. It sends a subset of cross-sectional reduced-rank models from R into Julia through JuliaCall. It is one-way: <strong>R → Julia</strong>. It does not run Julia models back through R, and it does not cover phylogeny, spatial, animal, kernel, or iSDM structure, nor the full <code>traits()</code> formula grammar.</p><p>For the admitted bridge surface versus the wider engine, see <a href="./gllvmtmb-parity">Capability parity</a>. The bridge rejects unsupported structures explicitly rather than silently changing the model.</p><h2 id="What-this-page-does-not-claim" tabindex="-1">What this page does not claim <a class="header-anchor" href="#What-this-page-does-not-claim" aria-label="Permalink to &quot;What this page does not claim {#What-this-page-does-not-claim}&quot;">​</a></h2><ul><li><p>Universal parity, or that every R workflow has an identical Julia counterpart.</p></li><li><p>Calibrated interval coverage on either side.</p></li><li><p>R-site navigation, which is maintained separately.</p></li></ul><p>For planned capability work, see the package <a href="./roadmap">Roadmap</a>.</p>',7))])}const v=r(s,[["render",u]]);export{b as __pageData,v as default};
